import sys

def main():
    data = sys.stdin.read().split()
    n, x, y = int(data[0]), int(data[1]), int(data[2])
    t = list(map(int, data[3:3 + n]))
    dx = x - y
    def feasible(k):
        base = k * y
        need = 0
        for v in t:
            if v > base:
                need += (v - base + dx - 1) // dx
                if need > k:
                    return False
        return need <= k
    lo, hi = 0, (max(t) + y - 1) // y
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    print(lo)

main()

